<?php
namespace ServSys\Admin;
use ServSys\PreventiveMaintenance\PMPlanRepository;
use ServSys\PreventiveMaintenance\PMPlanTermRepository;
use ServSys\PreventiveMaintenance\PMPlanService;
use ServSys\Users\Capabilities;
if(!defined('ABSPATH')){exit;}
final class PMPlansPage {
 public function register(): void {add_action('admin_menu',array($this,'register_menu'));add_action('admin_post_servsys_save_pm_plan',array($this,'save'));}
 public function register_menu(): void {add_submenu_page(null,'Preventive Maintenance Plans','Preventive Maintenance Plans',Capabilities::VIEW_PM_PLANS,'servsys-pm-plans',array($this,'render'));}
 public function render(): void {if(!current_user_can(Capabilities::VIEW_PM_PLANS)){wp_die(esc_html__('You do not have permission to view Preventive Maintenance plans.','servsys'));}// phpcs:ignore WordPress.Security.NonceVerification.Recommended -- Read-only admin navigation/search.
$edit=isset($_GET['edit'])?absint(wp_unslash($_GET['edit'])):0;$term=isset($_GET['s'])?sanitize_text_field(wp_unslash($_GET['s'])):'';$error=isset($_GET['servsys_error'])?sanitize_text_field(wp_unslash($_GET['servsys_error'])):'';$repo=new PMPlanRepository();echo '<div class="wrap"><h1>Preventive Maintenance Price Book</h1><p>PM Plans are company-specific templates. Term pricing is normalized so plans may use any contract length; customer agreements will snapshot the selected price separately.</p>';if($error){echo '<div class="notice notice-error inline"><p>'.esc_html($error).'</p></div>';}echo '<form method="get"><input type="hidden" name="page" value="servsys-pm-plans"><p class="search-box"><input type="search" name="s" value="'.esc_attr($term).'"> ';submit_button('Search PM Plans','secondary','',false);echo '</p></form><table class="widefat striped"><thead><tr><th>Description</th><th>T&amp;M Estimate</th><th>Term Prices</th><th>Status</th><th>Action</th></tr></thead><tbody>';$terms=new PMPlanTermRepository();foreach($repo->search($term,true) as $row){$prices=array();foreach($terms->for_plan((int)$row['id']) as $t){$prices[]=$this->term_label((int)$t['term_months']).': $'.number_format((float)$t['price'],2);}echo '<tr><td>'.esc_html($row['description']).'</td><td>$'.esc_html(number_format((float)$row['tm_estimate'],2)).'</td><td>'.esc_html(implode('; ',$prices)).'</td><td>'.($row['active']?'Active':'Inactive').'</td><td>';if(current_user_can(Capabilities::MANAGE_PM_PLANS)){echo '<a class="button button-small" href="'.esc_url(admin_url('admin.php?page=servsys-pm-plans&edit='.(int)$row['id'])).'">Edit</a>';}echo '</td></tr>';}echo '</tbody></table>';if(current_user_can(Capabilities::MANAGE_PM_PLANS)){$this->render_form($edit?$repo->find($edit):null);}echo '</div>';}
 private function render_form($plan): void {$plan=wp_parse_args($plan?:array(),array('id'=>0,'description'=>'','tm_estimate'=>0,'active'=>1));$terms=$plan['id']?(new PMPlanTermRepository())->for_plan((int)$plan['id']):array(array('term_months'=>12,'price'=>''),array('term_months'=>24,'price'=>''),array('term_months'=>36,'price'=>''));while(count($terms)<5){$terms[]=array('term_months'=>'','price'=>'');}echo '<h2>'.($plan['id']?'Edit':'Add').' PM Plan</h2><form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('servsys_save_pm_plan');echo '<input type="hidden" name="action" value="servsys_save_pm_plan"><input type="hidden" name="plan_id" value="'.esc_attr((string)$plan['id']).'"><p><label>Description<br><input class="regular-text" name="description" value="'.esc_attr($plan['description']).'" required></label></p><p><label>T&amp;M Estimate / Reference<br><input type="number" min="0" step="0.0001" name="tm_estimate" value="'.esc_attr((string)$plan['tm_estimate']).'" required></label></p><p><label><input type="checkbox" name="active" value="1" '.checked((int)$plan['active'],1,false).'> Active</label></p><h3>Term Pricing</h3><table class="widefat"><thead><tr><th>Term (months)</th><th>Price</th></tr></thead><tbody>';foreach($terms as $i=>$row){echo '<tr><td><input type="number" min="1" name="terms['.esc_attr((string)$i).'][term_months]" value="'.esc_attr((string)$row['term_months']).'"></td><td><input type="number" min="0" step="0.0001" name="terms['.esc_attr((string)$i).'][price]" value="'.esc_attr((string)$row['price']).'"></td></tr>';}echo '</tbody></table>';submit_button($plan['id']?'Save PM Plan':'Add PM Plan');echo '</form>';}
 // phpcs:ignore WordPress.Security.ValidatedSanitizedInput.InputNotSanitized -- Nested term rows are sanitized immediately before domain use.
 public function save(): void {check_admin_referer('servsys_save_pm_plan');if(!current_user_can(Capabilities::MANAGE_PM_PLANS)){wp_die(esc_html__('Permission denied.','servsys'));}$id=isset($_POST['plan_id'])?absint(wp_unslash($_POST['plan_id'])):0;try{$service=new PMPlanService();$id=$service->save(wp_unslash($_POST),$id);$terms_input=isset($_POST['terms'])?(array)wp_unslash($_POST['terms']):array();$terms_input=array_map(static function($row){$row=(array)$row;return array('term_months'=>absint($row['term_months']??0),'price'=>isset($row['price'])?(float)$row['price']:0);},$terms_input);$service->replace_terms($id,$terms_input);$url=admin_url('admin.php?page=servsys-pm-plans&edit='.$id);}catch(\InvalidArgumentException|\RuntimeException $e){$url=add_query_arg('servsys_error',$e->getMessage(),admin_url('admin.php?page=servsys-pm-plans'.($id?'&edit='.$id:'')));}wp_safe_redirect($url);exit;}
 private function term_label(int $months): string {return 0===$months%12?($months/12).' year'.(12===$months?'':'s'):$months.' months';}
}
